        except Exception as exc:  # noqa: BLE001
            last = exc
            if attempt < attempts - 1:
                time.sleep(min(2.0, 0.5 * (2 ** attempt)))
    raise RuntimeError(f"{self.name} failed after {attempts} attempt(s): {last}") from last

