# ── checking what an agent returns ───────────────────────────────────────────

def parse_agent_json(raw: str) -> dict:
    """Pull the JSON object out of an agent's final reply. Tolerates a ```json
    fence or prose around the object. Returns {} if there is no usable object."""
    t = re.sub(r"<think>.*?</think>", "", raw or "", flags=re.S | re.I).strip()
    if t.startswith("```"):
        t = re.sub(r"^```[a-zA-Z]*\s*", "", t).rstrip("`").strip()
    for candidate in (t, (re.search(r"\{.*\}", t, re.S) or [None])[0]):
        if not candidate:
            continue
        try:
            obj = json.loads(candidate)
        except (ValueError, TypeError):
            continue
        if isinstance(obj, dict):
            return obj
    return {}

