def _explain_empty(repo: Path) -> str:
    """Say WHY a folder produced no chunks, so the user knows what to fix."""
    from cortex.index.chunker import _SKIP_DIRS, _is_tool_install
    try:
        children = list(repo.iterdir())
    except OSError:
        children = []
    tool_copies = [c for c in children if c.is_dir() and _is_tool_install(c)]
    if tool_copies:
        return (f"nothing to index in {repo}: it only wraps a copy of Cortex itself "
                f"({tool_copies[0].name}), which is never indexed from a parent folder. "
                f"To index Cortex, use the inner folder: {tool_copies[0]}")
    if not children:
        return f"nothing to index: {repo} is empty."
    skipped = sorted(c.name for c in children
                     if c.is_dir() and (c.name in _SKIP_DIRS or c.name.startswith(".")))
    hint = f" (skipped folders here: {', '.join(skipped[:6])})" if skipped else ""
    return (f"nothing to index in {repo}: no supported source or text files were found"
            f"{hint}. Check that this is the repository's root folder.")

