    #toasts{left:12px;right:12px;bottom:12px;max-width:none}
  }
  @media (max-width: 560px){
    .theme-toggle #themeLabel{display:none}
    .user-av{display:none}
    .user-bubble{max-width:92%;font-size:14px;padding:10px 13px}
    .bot-av{width:24px;height:24px}
    .turn.bot{gap:8px}
    .empty h2{font-size:21px}
    .empty p{font-size:13px}
