    .hint{display:none}
    .tour-stop{padding:13px 13px}
    .tour-nav{flex-direction:column}
    .wt-sec h3{font-size:18px}
    .fv-overlay{padding:0}
    .fv-modal{max-height:100dvh;height:100dvh;border-radius:0}
  }

